package kome.common.data;
import net.minecraft.nbt.NBTTagCompound; import org.junit.Test; import static org.junit.Assert.*;
public class KOMEWarInactivityTest {
 @Test public void pressureIsDeterministicPersistentAndNeverChangesSeason(){KOMEWorldData d=new KOMEWorldData("w");KOMEWar w=new KOMEWar();w.id="w";w.status=KOMEWar.ACTIVE;w.sideOneFactions.add("gondor");w.sideTwoFactions.add("mordor");w.createdAtMillis=w.lastActivePressureAtMillis=10L;d.wars.put(w.id,w);assertEquals(10L,w.lastActivePressureAtMillis);String phase=d.warSeason.phase.name();KOMEWarService.recordHostilePressure(d,w,25L,"RELIEF");assertEquals(25L,w.lastActivePressureAtMillis);assertEquals(phase,d.warSeason.phase.name());assertFalse(KOMEWarService.isInactivityEligible(w,34L,10L));assertTrue(KOMEWarService.isInactivityEligible(w,35L,10L));assertTrue(KOMEWarService.isInactivityEligible(w,36L,10L));assertFalse(KOMEWarService.isInactivityEligible(w,999L,-1L));KOMEWarService.recordHostileCapture(d,"T1","mordor","gondor",null,"",40L,"TEST");assertEquals(40L,w.lastActivePressureAtMillis);NBTTagCompound n=w.writeToNBT();KOMEWar r=new KOMEWar();r.readFromNBT(n);assertEquals(40L,r.lastActivePressureAtMillis);}
}
